import java.util.function.BiFunction;
import java.util.function.IntUnaryOperator;
import java.util.function.LongBinaryOperator;
import java.util.function.LongUnaryOperator;

public class Main {

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		FastScanner scanner = new FastScanner();
		java.io.PrintWriter writer = new java.io.PrintWriter(System.out);
		execute(scanner, writer);
		writer.flush();
	}

	public void execute(FastScanner scanner, java.io.PrintWriter writer) {
		int n = scanner.nextInt();
		long k = scanner.nextLong();
		final long[] factorials = new long[n + 1], inverses = new long[n + 1];
		final int MOD = 998244353;
		factorials[0] = 1;
		for (int i = 0; i < n; ++i) factorials[i + 1] = factorials[i] * (i + 1) % MOD;
		inverses[n] = IntMath.pow((int) factorials[n], MOD - 2, MOD);
		for (int i = n; i > 0; --i) inverses[i - 1] = inverses[i] * i % MOD;
		BiFunction<Integer, Integer, Long> comb = (i, j) -> factorials[i] * inverses[j] % MOD * inverses[i - j] % MOD;
		if (k == 0) {
			writer.println(factorials[n]);
		} else if (k > n) {
			writer.println(0);
		} else {
			int k2 = (int) k;
			int k3 = n - k2;
			long total = 0;
			for (int i = 1; i <= k3; ++i) {
				long temp = comb.apply(k3, i) * IntMath.pow(i, n, MOD) % MOD;
				total += ((k3 - i) & 1) != 0 ? -temp : temp;
			}
			total = (total % MOD + MOD) % MOD;
			total = total * 2 * comb.apply(n, k2) % MOD;
			writer.println(total);
		}
	}

	static class FastScanner {
		private final java.io.InputStream inStream = System.in;
		private final byte[] buffer = new byte[1024];
		private int pointer = 0;
		private int bufferLength = 0;
		private boolean hasNextByte() {
			if (pointer < bufferLength) return true;
			pointer = 0;
			try {
				bufferLength = inStream.read(buffer);
			} catch (java.io.IOException e) {
				e.printStackTrace();
			}
			return bufferLength > 0;
		}
		private byte readByte() {
			return hasNextByte() ? buffer[pointer++] : -1;
		}
		private static boolean isPrintable(byte c) {
			return c > 32 || c < 0;
		}
		private static boolean isDigit(int c) {
			return '0' <= c && c <= '9';
		}
		public boolean hasNext() {
			while (hasNextByte() && !isPrintable(buffer[pointer])) pointer++;
			return hasNextByte();
		}
		public String next() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			byte b;
			while (isPrintable(b = readByte())) sb.appendCodePoint(b);
			return sb.toString();
		}
		public long nextLong() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			long number = 0;
			try {
				byte b = readByte();
				if (b == '-') {
					while (isDigit(b = readByte())) number = number * 10 - (b - '0');
					return number;
				} else if (!isDigit(b)) throw new NumberFormatException();
				do number = number * 10 + (b - '0'); while (isDigit(b = readByte()));
			} catch (java.util.NoSuchElementException e) {
			}
			return number;
		}
		public int nextInt() {
			if (!hasNext()) throw new java.util.NoSuchElementException();
			int number = 0;
			try {
				byte b = readByte();
				if (b == '-') {
					while (isDigit(b = readByte())) number = number * 10 - (b - '0');
					return number;
				} else if (!isDigit(b)) throw new NumberFormatException();
				do number = number * 10 + (b - '0'); while (isDigit(b = readByte()));
			} catch (java.util.NoSuchElementException e) {
			}
			return number;
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}
