using namespace std;

long long pow_mod(long long base, long long exp, int mod) {
    long long result = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) result = result * cur % mod;
        cur = cur * cur % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    const int MOD = 998244353;
    vector<long long> factorials(n + 1, 1), inverses(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        factorials[i + 1] = factorials[i] * (i + 1) % MOD;
    }
    inverses[n] = pow_mod(factorials[n], MOD - 2, MOD);
    for (int i = n; i > 0; --i) {
        inverses[i - 1] = inverses[i] * i % MOD;
    }
    auto comb = [&](int i, int j) -> long long {
        if (j < 0 || j > i) return 0;
        return factorials[i] * inverses[j] % MOD * inverses[i - j] % MOD;
    };
    if (k == 0) {
        cout << factorials[n] << "\n";
    } else if (k > n) {
        cout << 0 << "\n";
    } else {
        int k2 = (int)k;
        int k3 = n - k2;
        long long total = 0;
        for (int i = 1; i <= k3; ++i) {
            long long temp = comb(k3, i) * pow_mod(i, n, MOD) % MOD;
            if (((k3 - i) & 1) != 0) {
                total -= temp;
            } else {
                total += temp;
            }
        }
        total = (total % MOD + MOD) % MOD;
        total = total * 2 % MOD;
        total = total * comb(n, k2) % MOD;
        cout << total << "\n";
    }
    return 0;
}
